package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A period on a sheet: a named run of days from its from-date to its to-date, both inclusive. A
 *  claim belongs to the period whose days contain its due-by. A closed period keeps the due-total it
 *  had when it was closed, and no claim due by a day inside it can be changed. A soft-closed period
 *  keeps its due-total as a closed one does, but claims due inside it can still be added and changed. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Whether a steward has locked the period: a locked period cannot be reopened. */
    @Column(name = "locked", nullable = false)
    private boolean locked;

    /** The most open or pending claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer claimCap;

    /** Each person's due-total for the period, by the person's id, fixed when it was closed; empty
     *  while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** Each person's carried figure for the period, by the person's id, fixed when it was closed or
     *  soft-closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> personCarried = new HashMap<>();

    /** Each person's opening balance for the period, by the person's id: what pasted opening
     *  balances have added to their carried figure for it. Kept while the period is open or closed. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "opening", nullable = false)
    private Map<Long, BigDecimal> personOpenings = new HashMap<>();

    /** The last number given to a claim in the period under period numbering; only ever moved on by
     *  {@link PeriodRepository#advanceClaimNumber}. */
    @Column(name = "last_claim_number", insertable = false, updatable = false)
    private int lastClaimNumber;

    protected Period() {
    }

    /** A period as a revision in its sheet's history has it, detached: never saved. */
    static Period revised(String sheetId, Long id, String name, LocalDate fromDate, LocalDate toDate,
            boolean closed, boolean softClosed, BigDecimal closedTotal, Map<Long, BigDecimal> personTotals,
            Map<Long, BigDecimal> personCarried, Map<Long, BigDecimal> personOpenings, Integer claimCap,
            boolean locked) {
        Period period = new Period(sheetId, name, fromDate, toDate, claimCap);
        period.id = id;
        period.closed = closed;
        period.softClosed = softClosed;
        period.locked = locked;
        period.closedTotal = closedTotal;
        period.personTotals.putAll(personTotals);
        period.personCarried.putAll(personCarried);
        period.personOpenings.putAll(personOpenings);
        return period;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this(sheetId, name, fromDate, toDate, null);
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer claimCap) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.claimCap = claimCap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Add an amount to a person's opening balance for the period. */
    public void addOpening(Long personId, BigDecimal amount) {
        personOpenings.merge(personId, amount, BigDecimal::add);
    }

    /** Close the period, fixing each person's due-total and carried figure for it at what they are
     *  now, and its own due-total at the sum of the due-totals. */
    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closed = true;
        this.softClosed = false;
        fix(personTotals, personCarried);
    }

    /** Soft-close the period, fixing its due-totals as {@link #close} does while leaving claims dated
     *  inside it open to change. */
    public void softClose(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.softClosed = true;
        fix(personTotals, personCarried);
    }

    private void fix(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.personCarried.clear();
        this.personCarried.putAll(personCarried);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Fold one person's fixed due-total, carried figure and opening balance for the period into another's (the one
     *  was merged into the other); the period's own due-total stays as it is. */
    public void mergePersonTotal(Long fromId, Long intoId) {
        BigDecimal from = personTotals.remove(fromId);
        if (from != null) {
            personTotals.merge(intoId, from, BigDecimal::add);
        }
        BigDecimal carried = personCarried.remove(fromId);
        if (carried != null) {
            personCarried.merge(intoId, carried, BigDecimal::add);
        }
        BigDecimal opening = personOpenings.remove(fromId);
        if (opening != null) {
            personOpenings.merge(intoId, opening, BigDecimal::add);
        }
    }

    /** Drop one person's fixed due-total, carried figure and opening balance for the period (they left the sheet);
     *  the period's own due-total stays as it is. */
    public void dropPersonTotal(Long personId) {
        personTotals.remove(personId);
        personCarried.remove(personId);
        personOpenings.remove(personId);
    }

    /** Reopen the period: its due-totals and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
        this.personCarried.clear();
    }
}

    /** Generate the four calendar quarters of the year, each running from the first day of its
     *  first month to the last day of its third month and named yyyy-Qn; a quarter whose name is in
     *  use on the sheet, or whose days overlap a period on it, is left out. */
    @Transactional
    public synchronized List<Period> generateQuarters(String sheetId, String user, int year) {
        sheets.load(sheetId, user);
        List<Period> made = new ArrayList<>();
        for (int quarter = 1; quarter <= 4; quarter++) {
            String name = year + "-Q" + quarter;
            LocalDate first = LocalDate.of(year, quarter * 3 - 2, 1);
            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
            made.add(saved);
        }
        history.record(sheetId);
        return made;
    }

    /** The fiscal year a day falls in (FYyyyy), with fiscal years starting on the first day of the
     *  month: named by the calendar year that first day falls in. */
    public static String fiscalYear(LocalDate day, int fiscalStartMonth) {
        return "FY" + (day.getMonthValue() >= fiscalStartMonth ? day.getYear() : day.getYear() - 1);
    }

    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
     *  not allow the user's role to close, or it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        return closeOpen(sheetId, user, period, "");
    }

    /** Soft-close a period, fixing its due-total and each person's for it at what they are now while
     *  claims dated inside it stay open to change; refused when the permission matrix does not allow
     *  the user's role to close, or it is already closed or soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        period.softClose(personTotals(sheetId, period), personCarried(sheetId, period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString());
        history.record(sheetId);
        return saved;
    }

    /** Close every open period on the sheet whose to-date plus the grace days is before the day,
     *  earliest to-date first, each as a close by hand would, its record marked auto=yes. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void autoClose(String sheetId, String user, int graceDays, LocalDate day) {
        for (Period period : periods.findOpenEndingBefore(sheetId, day.minusDays(graceDays))) {
            closeOpen(sheetId, user, period, " auto=yes");
        }
    }

    /** Close an open period, fixing its due-total at what it is now; the suffix ends its record. */
    private Period closeOpen(String sheetId, String user, Period period, String suffix) {
        period.close(personTotals(sheetId, period), personCarried(sheetId, period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString() + suffix);
        history.record(sheetId);
        return saved;
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; refused when the permission matrix
     *  does not allow the user's role to reopen, the period is not closed, or it is locked. */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "reopen")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
        }
        if (period.isLocked()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is locked");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        history.record(sheetId);
        return saved;
    }

    /** Lock or unlock a period; refused unless the user acts as a steward, or when it is already
     *  locked (or, to unlock, not locked). */
    @Transactional
    public Period lock(String sheetId, String user, long periodId, boolean lock) {
        sheets.load(sheetId, user);
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward may " + (lock ? "lock" : "unlock") + " a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isLocked() == lock) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    lock ? "That period is already locked" : "That period is not locked");
        }
        period.setLocked(lock);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
                + " period=" + saved.getName());
        history.record(sheetId);
        return saved;
    }

    /** Each person's due-total for a period, by the person's id: the due figures of their claims
     *  whose due-by falls in it and that count by their status at its end, skipping those with no due
     *  and those the live rules leave out (see Dues#countsAsOf). */
    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, BigDecimal> totals = new HashMap<>();
        for (Long id : byId.keySet()) {
            totals.put(id, BigDecimal.ZERO.setScale(2));
        }
